#include <stdio.h>

int main() {
    int a[] = {3, 9, 14, 21, 35, 47, 60};
    int target = 35;
    int low = 0, high = 6, found = -1;
    while (low <= high) {
        int mid = low + (high - low) / 2;
        if (a[mid] == target) {
            found = mid;
            break;
        }
        if (a[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }
    printf("%d\n", found);
    return 0;
}
